## MSTest Comparison Assertions for Boundary Checking

MSTest 3.x+ provides these comparison assertions (from `Assert`):

```csharp
Assert.IsGreaterThan(lowerBound, actual);   // actual > lowerBound
Assert.IsLessThan(upperBound, actual);      // actual < upperBound
Assert.IsInRange(actual, low, high);        // low <= actual <= high
```

### Example Tests for Your `ScoreCalculator`

```csharp
[TestClass]
public sealed class ScoreCalculatorTests
{
    private readonly ScoreCalculator _calc = new();

    [TestMethod]
    public void CalculatePercentage_PartialScore_ReturnsValueInRange()
    {
        var result = _calc.CalculatePercentage(7, 10);

        Assert.AreEqual(70.0, result);
    }

    [TestMethod]
    [DataRow(9, 10, 90.0)]
    [DataRow(8, 10, 80.0)]
    [DataRow(7, 10, 70.0)]
    [DataRow(6, 10, 60.0)]
    [DataRow(5, 10, 50.0)]
    public void CalculatePercentage_VariousScores_ReturnsExpected(
        int correct, int total, double expected)
    {
        Assert.AreEqual(expected, _calc.CalculatePercentage(correct, total));
    }

    [TestMethod]
    public void NormalizeScore_BelowMax_ReturnsValueInRange()
    {
        var result = _calc.NormalizeScore(75, 150);

        Assert.IsInRange(result, 0.0, 100.0);  // bounded [0, 100]
        Assert.AreEqual(50.0, result);
    }

    [TestMethod]
    public void NormalizeScore_ExceedsMax_CapsAt100()
    {
        var result = _calc.NormalizeScore(120, 100);

        Assert.AreEqual(100.0, result);  // capped
    }

    [TestMethod]
    public void NormalizeScore_ValidInput_ResultIsNonNegative()
    {
        var result = _calc.NormalizeScore(0, 100);

        Assert.IsGreaterThan(-1.0, result);  // result > -1 (i.e., >= 0)
    }

    [TestMethod]
    [DataRow(90.0, "A")]
    [DataRow(89.99, "B")]
    [DataRow(80.0, "B")]
    [DataRow(79.5, "C")]
    [DataRow(70.0, "C")]
    [DataRow(60.0, "D")]
    [DataRow(59.9, "F")]
    public void GetGrade_AtBoundaries_ReturnsCorrectGrade(double pct, string expected)
    {
        Assert.AreEqual(expected, _calc.GetGrade(pct));
    }

    [TestMethod]
    public void CalculatePercentage_ZeroTotal_Throws()
    {
        Assert.ThrowsExactly<ArgumentOutOfRangeException>(
            () => _calc.CalculatePercentage(0, 0));
    }

    [TestMethod]
    public void CalculatePercentage_CorrectExceedsTotal_Throws()
    {
        Assert.ThrowsExactly<ArgumentOutOfRangeException>(
            () => _calc.CalculatePercentage(11, 10));
    }
}
```

### Key Takeaways

| Assertion | Use case |
|-----------|----------|
| `Assert.IsGreaterThan(bound, actual)` | Verify score exceeds a minimum |
| `Assert.IsLessThan(bound, actual)` | Verify score stays below a cap |
| `Assert.IsInRange(actual, low, high)` | Verify normalized scores stay in `[0, 100]` |
| `Assert.AreEqual(expected, actual)` | Exact boundary values (90.0 → "A") |
| `Assert.ThrowsExactly<T>(...)` | Invalid inputs throw at boundaries |

Use `Assert.IsInRange` for "result stays within bounds" checks, and `DataRow` with exact equality for testing each grade boundary precisely.
